+export function normalizePhone(input, regionHint = null) {
+  if (typeof input !== 'string') {
+    throw new TypeError('Expected string input');
+  }
+
+  const EMPTY = '';
+  const FORMAT = 'FORMAT';
+  const LENGTH = 'LENGTH';
+  const REGION = 'REGION';
+
+  // Strip spaces, hyphens, parentheses, dots
+  let cleaned = input.replace(/[ \-\(\)\.]/g, '');
+
+  // Check for letters or malformed punctuation (anything not 0-9, +)
+  if (/[^0-9+]/.test(cleaned)) {
+    return { normalized: EMPTY, valid: false, reason: FORMAT };
+  }
+
+  // Handle international prefix conversion
+  let hasIntlPrefix = false;
+  let digitsOnly = cleaned.replace(/^\+/, '');
+
+  if (digitsOnly.startsWith('00')) {
+    digitsOnly = digitsOnly.slice(2);
+    hasIntlPrefix = true;
+  } else if (digitsOnly.startsWith('+')) {
+    digitsOnly = digitsOnly.slice(1);
+    hasIntlPrefix = true;
+  }
+
+  // If no international prefix and no region hint, return REGION error
+  if (!hasIntlPrefix && !regionHint) {
+    return { normalized: EMPTY, valid: false, reason: REGION };
+  }
+
+  // Apply region-specific rules
+  if (regionHint === 'BE') {
+    // BE: leading 0 local becomes +32 plus digits after 0; otherwise prefix +32
+    if (digitsOnly.startsWith('0')) {
+      // Remove the leading 0 and prepend +32
+      const localDigits = digitsOnly.slice(1);
+      const normalized = '+32' + localDigits;
+      // Validate length: +32 + up to 9 digits = 11-12 chars total (including +)
+      // Belgium phone numbers are typically 9 digits after country code
+      if (normalized.length < 5 || normalized.length > 14) {
+        return { normalized: EMPTY, valid: false, reason: LENGTH };
+      }
+      return { normalized, valid: true, reason: '' };
+    } else {
+      // Otherwise prefix +32
+      const normalized = '+32' + digitsOnly;
+      if (normalized.length < 5 || normalized.length > 14) {
+        return { normalized: EMPTY, valid: false, reason: LENGTH };
+      }
+      return { normalized, valid: true, reason: '' };
+    }
+  } else if (regionHint === 'US') {
+    // US: allow 10 digits and prefix +1, or 11 digits starting 1 and prefix +
+    if (digitsOnly.length === 10) {
+      const normalized = '+1' + digitsOnly;
+      return { normalized, valid: true, reason: '' };
+    } else if (digitsOnly.length === 11 && digitsOnly.startsWith('1')) {
+      // Remove leading 1 and prefix +
+      const localDigits = digitsOnly.slice(1);
+      const normalized = '+' + localDigits;
+      return { normalized, valid: true, reason: '' };
+    } else {
+      return { normalized: EMPTY, valid: false, reason: LENGTH };
+    }
+  } else {
+    // No region hint and has international prefix
+    // Validate length: + followed by 8..15 digits
+    if (digitsOnly.length < 8 || digitsOnly.length > 15) {
+      return { normalized: EMPTY, valid: false, reason: LENGTH };
+    }
+    const normalized = '+' + digitsOnly;
+    return { normalized, valid: true, reason: '' };
+  }
+}

